static BYTE *read_file(const char *name, DWORD *size)
{
    HANDLE f = CreateFileA(name, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL);
    BYTE *buf;

    if (f == INVALID_HANDLE_VALUE) return NULL;
    *size = GetFileSize(f, NULL);
    buf = malloc(*size + 1);
    ReadFile(f, buf, *size, size, NULL);
    CloseHandle(f);
    return buf;
}

static void write_file(const char *name, const void *data, DWORD size)
{
    HANDLE f = CreateFileA(name, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, 0, NULL);
    DWORD written;
    WriteFile(f, data, size, &written, NULL);
    CloseHandle(f);
}

static void compare_masked(const char *what, const BYTE *got, DWORD got_size, const BYTE *want, DWORD want_size,
                           DWORD id_off, DWORD time_off)
{
    BYTE *a = malloc(got_size), *b = malloc(want_size);
    DWORD i;

    CHECK(got_size == want_size, "%s: size %lu, expected %lu", what, got_size, want_size);
    if (got_size == want_size)
    {
        memcpy(a, got, got_size);
        memcpy(b, want, want_size);
        memset(a + id_off, 0, 16); memset(b + id_off, 0, 16);
        memset(a + time_off, 0, 13); memset(b + time_off, 0, 13);
        for (i = 0; i < got_size && a[i] == b[i]; i++) {}
        CHECK(i == got_size, "%s: first difference at byte %lu (%02x, expected %02x)", what, i, a[i], b[i]);
    }
    free(a); free(b);
}

static void test_cdf(void)
{
    WCHAR cdfw[] = L"winetest.cdf";
    CRYPTCATCDF *cdf;
    CRYPTCATATTRIBUTE *attr = NULL;
    CRYPTCATMEMBER *member = NULL;
    WCHAR *tag = NULL;
    BYTE *cat;
    DWORD size;
    int attrs = 0, members = 0;

    write_file("winetest.cdf", cdf_text, sizeof(cdf_text) - 1);
    DeleteFileA("winetest.cat");
    cdf = CryptCATCDFOpen(cdfw, NULL);
    CHECK(cdf != NULL, "CDF open %lu", GetLastError());
    if (!cdf) return;
    while ((attr = CryptCATCDFEnumCatAttributes(cdf, attr, NULL))) attrs++;
    while ((tag = CryptCATCDFEnumMembersByCDFTagEx(cdf, tag, NULL, &member, FALSE, NULL)))
    {
        CHECK(!lstrcmpW(tag, L"hashme"), "member tag %ls", tag);
        members++;
    }
    CHECK(attrs == 2 && members == 1, "enumerated %d attributes and %d members", attrs, members);
    CHECK(CryptCATCDFClose(cdf), "CDF close %lu", GetLastError());

    cat = read_file("winetest.cat", &size);
    CHECK(cat != NULL, "catalog not written");
    if (cat) compare_masked("makecat catalog", cat, size, sample_cat, sizeof(sample_cat), SAMPLE_ID_OFF, SAMPLE_TIME_OFF);
    free(cat);
    DeleteFileA("winetest.cat");
    DeleteFileA("winetest.cdf");
}

